import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, TouchableOpacity, Button, Alert } from 'react-native';
import AboutScreen from './AboutScreen';

const WIN_LINES = [
  [0,1,2],[3,4,5],[6,7,8],
  [0,3,6],[1,4,7],[2,5,8],
  [0,4,8],[2,4,6]
];

function checkWinner(board) {
  for (const [a,b,c] of WIN_LINES) {
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return board[a];
    }
  }
  if (board.every(Boolean)) return 'Tie';
  return null;
}

function availableMoves(board) {
  const moves = [];
  board.forEach((v,i)=>{ if (!v) moves.push(i); });
  return moves;
}

function minimax(board, player, aiPlayer, humanPlayer) {
  const winner = checkWinner(board);
  if (winner === aiPlayer) return {score: 1};
  if (winner === humanPlayer) return {score: -1};
  if (winner === 'Tie') return {score: 0};

  const moves = availableMoves(board);

  if (player === aiPlayer) {
    let best = {score: -Infinity, index: null};
    for (const m of moves) {
      board[m] = player;
      const res = minimax(board, humanPlayer, aiPlayer, humanPlayer);
      board[m] = null;
      if (res.score > best.score) {
        best = {score: res.score, index: m};
      }
      if (best.score === 1) break;
    }
    return best;
  } else {
    let best = {score: Infinity, index: null};
    for (const m of moves) {
      board[m] = player;
      const res = minimax(board, aiPlayer, aiPlayer, humanPlayer);
      board[m] = null;
      if (res.score < best.score) {
        best = {score: res.score, index: m};
      }
      if (best.score === -1) break;
    }
    return best;
  }
}

export default function App() {
  const [board, setBoard] = useState(Array(9).fill(null));
  const [human, setHuman] = useState('X');
  const [ai, setAI] = useState('O');
  const [turn, setTurn] = useState('X');
  const [status, setStatus] = useState('Choose symbol to start');
  const [easy, setEasy] = useState(false);
  const [screen, setScreen] = useState('game'); // 'game' or 'about'

  useEffect(()=>{
    const w = checkWinner(board);
    if (w) {
      if (w === 'Tie') setStatus('Result: Tie');
      else setStatus(`Result: ${w} wins`);
    } else {
      setStatus(`${turn}'s turn`);
      if (turn === ai) {
        // AI move
        const timeout = setTimeout(()=>{
          aiMove();
        }, 200);
        return ()=>clearTimeout(timeout);
      }
    }
  }, [board, turn]);

  function reset(newHuman='X'){
    setBoard(Array(9).fill(null));
    setHuman(newHuman);
    setAI(newHuman === 'X' ? 'O' : 'X');
    setTurn('X');
    setStatus('New game — choose symbol or play');
  }

  function aiMove(){
    const b = [...board];
    const moves = availableMoves(b);
    if (moves.length === 0) return;
    let choice = null;
    if (easy) {
      choice = moves[Math.floor(Math.random()*moves.length)];
    } else {
      const res = minimax(b, ai, ai, human);
      choice = res.index;
    }
    if (choice == null) choice = moves[0];
    b[choice] = ai;
    setBoard(b);
    setTurn(human);
  }

  function onCellPress(i){
    if (board[i] || checkWinner(board)) return;
    if (turn !== human) return;
    const b = [...board];
    b[i] = human;
    setBoard(b);
    setTurn(ai);
  }

  function chooseSymbol(sym){
    reset(sym);
    setHuman(sym);
    setAI(sym === 'X' ? 'O' : 'X');
    // If choosing O, AI (X) starts immediately
    if (sym === 'O') setTurn('X');
    else setTurn('X');
  }

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.appTitle}>TicTacToe</Text>
        <View style={styles.navButtons}>
          <TouchableOpacity 
            style={[styles.navBtn, screen === 'game' && styles.navBtnActive]} 
            onPress={() => setScreen('game')}
          >
            <Text style={[styles.navBtnText, screen === 'game' && styles.navBtnTextActive]}>Game</Text>
          </TouchableOpacity>
          <TouchableOpacity 
            style={[styles.navBtn, screen === 'about' && styles.navBtnActive]} 
            onPress={() => setScreen('about')}
          >
            <Text style={[styles.navBtnText, screen === 'about' && styles.navBtnTextActive]}>About</Text>
          </TouchableOpacity>
        </View>
      </View>

      {screen === 'game' ? (
        <View style={styles.gameContainer}>
          <Text style={styles.status}>{status}</Text>

          <View style={styles.board}>
            {board.map((cell, i)=> (
              <TouchableOpacity key={i} style={styles.cell} onPress={()=>onCellPress(i)}>
                <Text style={[styles.cellText, cell==='X' ? styles.x : styles.o]}>{cell || ''}</Text>
              </TouchableOpacity>
            ))}
          </View>

          <View style={styles.row}>
            <Button title="New Game (X)" onPress={()=>chooseSymbol('X')} />
            <View style={{width:12}} />
            <Button title="New Game (O)" onPress={()=>chooseSymbol('O')} />
          </View>

          <View style={[styles.row,{marginTop:12}]}> 
            <Button title={easy?"Difficulty: Easy":"Difficulty: Hard"} onPress={()=>setEasy(!easy)} />
            <View style={{width:12}} />
            <Button title="Reset Board" onPress={()=>reset(human)} />
          </View>

          <Text style={styles.note}>Tip: In Hard mode the AI plays optimally.</Text>
        </View>
      ) : (
        <AboutScreen />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex:1, backgroundColor:'#fff' },
  header: { backgroundColor:'#1a73e8', paddingTop:16, paddingBottom:12, paddingHorizontal:20 },
  appTitle: { fontSize:28, fontWeight:'700', color:'#fff', marginBottom:12 },
  navButtons: { flexDirection:'row', gap:8 },
  navBtn: { paddingHorizontal:16, paddingVertical:8, borderRadius:6, backgroundColor:'rgba(255,255,255,0.2)' },
  navBtnActive: { backgroundColor:'#fff' },
  navBtnText: { fontSize:14, fontWeight:'600', color:'#fff' },
  navBtnTextActive: { color:'#1a73e8' },
  gameContainer: { flex:1, alignItems:'center', justifyContent:'center', padding:20 },
  title: { fontSize:28, fontWeight:'700', marginBottom:8 },
  status: { fontSize:16, marginBottom:14 },
  board: { width:300, height:300, flexDirection:'row', flexWrap:'wrap', borderWidth:2, borderColor:'#333', marginBottom:20 },
  cell: { width:'33.3333%', height:'33.3333%', borderWidth:1, borderColor:'#999', alignItems:'center', justifyContent:'center' },
  cellText: { fontSize:36, fontWeight:'700' },
  x: { color:'#1a73e8' },
  o: { color:'#d93025' },
  row: { flexDirection:'row', marginTop:14 },
  note: { marginTop:14, color:'#666' }
});
